/** The shell dictionary and the catalog texts in the current language. */
export function useCatalogT(): { t: Dictionary; c: CatalogDictionary; english: boolean } {
  const t = useT();
  const english = t === DICTIONARIES.en;
  return { t, c: english ? en : ar, english };
}

export const CATALOG_DICTIONARIES = { ar, en };

/** A localized message for an API failure, including catalog conflict reasons. */
export function catalogError(t: Dictionary, c: CatalogDictionary, error: unknown): string {
  if (!(error instanceof StaffApiError)) {
    return errorMessage(t, error);
  }
  if (error.code === "CONFLICT") {
    const reason = String(error.details.reason ?? "");
    const missing = Array.isArray(error.details.missing)
      ? (error.details.missing as string[])
          .map((m) => c.publishMissing[m] ?? m)
          .join(c.listSeparator)
      : "";
    return (c.conflicts[reason] ?? c.conflict).replace("{missing}", missing);
  }
  if (error.code === "NOT_FOUND") {
    return c.notFound;
  }
  if (error.code === "RATE_LIMITED") {
    return c.rateLimited;
  }
  return errorMessage(t, error);
}
